class Solution {
public:
    vector<int> kthSmallestPrimeFraction(vector<int>& arr, int k) {
        int n = arr.size();
        double l = 0, r = 1;
        int best_i = 0, best_j = 1;

        for (int iter = 0; iter < 50; ++iter) {
            double mid = (l + r) / 2;
            int count = 0;
            int i = 0;
            int curr_best_i = 0, curr_best_j = 1;

            for (int j = 1; j < n; ++j) {
                while (i + 1 < j && arr[i + 1] <= mid * arr[j]) {
                    i++;
                }
                if (arr[i] <= mid * arr[j]) {
                    count += i + 1;
                    if (arr[i] * curr_best_j > curr_best_i * arr[j]) {
                        curr_best_i = arr[i];
                        curr_best_j = arr[j];
                    }
                }
            }

            if (count >= k) {
                r = mid;
                best_i = curr_best_i;
                best_j = curr_best_j;
            } else {
                l = mid;
            }
        }

        return {best_i, best_j};
    }
};
